'use strict';
let remote=null,busy=false,connected=false;
const localDraw=draw;
function controls(enabled){for(const id of ['toggle','close','example'])$(id).disabled=!enabled;document.querySelector('#config button').disabled=!enabled;}
async function api(path,payload){const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),12000);try{const r=await fetch('/api/'+path,{method:payload?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:payload?{'Content-Type':'application/json'}:{},body:payload?JSON.stringify(payload):undefined,signal:controller.signal});if(!r.headers.get('content-type')?.includes('application/json'))throw Error('Inicia sesión en el proyecto privado o espera a que termine el despliegue.');const value=await r.json();if(!r.ok)throw Error(value.error||'Error del servidor');if(value.mode!=='generated-paper'||value.broker_connected!==false)throw Error('Respuesta inesperada del motor de simulación');return value;}finally{clearTimeout(timeout);}}
function remoteDraw(){if(!remote)return localDraw();const c=$('chart'),r=c.getBoundingClientRect();if(!r.width)return;const dpr=window.devicePixelRatio||1,w=r.width,h=340;c.width=w*dpr;c.height=h*dpr;const x=c.getContext('2d');x.scale(dpr,dpr);const prices=remote.prices;if(prices.length<2){x.fillStyle='#9ab4cf';x.fillText('Esperando precios generados…',20,40);return;}const lo=Math.min(...prices)-.0005,hi=Math.max(...prices)+.0005;const y=p=>h-30-(p-lo)/(hi-lo)*(h-60);x.font='11px system-ui';for(let i=0;i<5;i++){const p=lo+(hi-lo)*i/4;x.strokeStyle='#243a4e';x.beginPath();x.moveTo(0,y(p));x.lineTo(w-60,y(p));x.stroke();x.fillStyle='#9ab4cf';x.fillText(p.toFixed(5),w-58,y(p)+4);}x.strokeStyle='#16c8bc';x.lineWidth=2;x.beginPath();prices.forEach((p,i)=>i?x.lineTo(i*(w-70)/(prices.length-1)+5,y(p)):x.moveTo(5,y(p)));x.stroke();x.fillStyle='#9ab4cf';x.fillText('Ticks sintéticos · un paso por minuto · no representan velas M15',10,h-5);}
function showRemote(){if(!remote)return;$('balance').textContent=money(remote.balance);$('profit').textContent=money(remote.balance-1000);$('risk').textContent=remote.open_risk_percent.toFixed(2)+'% / 2%';$('count').textContent=remote.trades.length+' / 2';$('status').textContent=remote.active?'● Motor simulado activo':'● Entradas simuladas pausadas';$('toggle').textContent=remote.active?'Pausar entradas':'Activar motor simulado';$('risk-label').textContent=remote.risk+'%';if(document.activeElement!==$('risk-input'))$('risk-input').value=remote.risk;document.querySelector('.connection').replaceChildren();const span=document.createElement('span');span.textContent='● Motor simulado · Conectado';const small=document.createElement('small');small.textContent='OANDA sin conectar';document.querySelector('.connection').append(span,small);document.querySelector('.chart-head span').textContent='Ticks generados · SMA 5/20';document.querySelector('.chart-head b').textContent=remote.price.toFixed(5);document.querySelector('.controls p').textContent='Cruce de medias sobre precios sintéticos. Estrategia educativa sin validar.';document.querySelector('.chart p').textContent='Equity simulada: '+money(remote.equity)+' · Pérdida diaria: '+remote.loss_percent+'%';$('trades').replaceChildren();for(const t of remote.trades)row($('trades'),['EUR/USD',t.direction===1?'Compra':'Venta',t.units,t.entry.toFixed(5),t.stop.toFixed(5),t.target.toFixed(5),money(t.profit)]);if(!remote.trades.length)row($('trades'),['Sin posiciones simuladas abiertas.']);$('history').replaceChildren();for(const t of remote.history)row($('history'),[t.time,'EUR/USD',t.units,money(t.profit)]);if(!remote.history.length)row($('history'),['Sin cierres simulados.']);$('activity').replaceChildren();for(const e of remote.events){const li=document.createElement('li');li.textContent=e;$('activity').append(li);}$('example').textContent='Avanzar un paso simulado';$('server-state').textContent='Conectado a Netlify · paso automático cada minuto · último paso: '+(remote.last_tick||'pendiente');remoteDraw();}

async function refresh(){if(busy)return;busy=true;try{remote=await api('state');connected=true;showRemote();controls(true);}catch(e){connected=false;controls(false);$('status').textContent='● Estado remoto sin confirmar';$('server-state').textContent=e.message;document.querySelector('.connection').textContent='● Sin respuesta del motor · OANDA desconectado';notice('No se puede confirmar el estado del motor. '+e.message);}finally{busy=false;}}
async function sendCommand(action,risk){if(busy||!connected)return notice('Espera a que el motor esté conectado.');busy=true;controls(false);const id=crypto.randomUUID();try{remote=await api('command',{action,risk,id});showRemote();notice('Cambio guardado en Netlify. OANDA sigue desconectado.');}catch(e){connected=false;notice('No se confirmó el cambio. Actualiza el estado antes de volver a intentarlo. '+e.message);}finally{busy=false;controls(connected);}}
$('toggle').onclick=()=>sendCommand(remote?.active?'pause':'start');
$('close').onclick=()=>confirm('¿Pausar entradas y cerrar todas las posiciones simuladas?')&&sendCommand('close');
$('example').onclick=()=>sendCommand('step');
$('config').onsubmit=e=>{e.preventDefault();sendCommand('config',Number($('risk-input').value));};
$('refresh-server').onclick=refresh;
$('reset').onclick=()=>notice('El historial remoto se conserva. No se borra desde el panel.');
$('export').onclick=()=>{if(!connected||!remote)return notice('Actualiza el estado antes de exportar.');const rows=['fecha,par,direccion,unidades,resultado_simulado_usd,motivo,fuente_datos,modelo',...remote.history.map(t=>[JSON.stringify(t.time),'EUR_USD',t.direction===1?'compra':'venta',t.units,t.profit,JSON.stringify(t.reason),t.data_source,t.model].join(','))];const u=URL.createObjectURL(new Blob([rows.join('\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='historial-motor-simulado.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
draw=remoteDraw;
controls(false);$('status').textContent='● Conectando al motor de Netlify…';document.querySelector('.connection').textContent='● Conectando · OANDA desconectado';
refresh();setInterval(()=>{if(!document.hidden)refresh();},15000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});
